def write_report(source, target):
    names = []
    with open(source, encoding="utf-8") as handle:
        for line in handle:
            name = line.strip().title()
            if name != "":
                names.append(name)
    with open(target, "w", encoding="utf-8") as handle:
        handle.write(f"Participants: {len(names)}\n")
        for name in names:
            handle.write(name + "\n")
    return len(names)

print(write_report("guests.txt", "report.txt"))
